 void StartPage(){if(S["phase"].Text=="select_block"){Label(_body,"同一片河谷，不同的第一步。",27,Ink);Label(_body,"选择登陆位置，随后从本次起源中确定最初居民与补给。",18,Muted);var row=Row(_body,"Landing Sites",460);var names=new[]{"河湾","林缘旧村","北部高台"};var notes=new[]{"临水平地，邻近水岸。先铺开生活供给，再选择工业方向。","森林与既有住区相接。地块条件改变后续方案的价值。","高地与开阔地并存。保留水岸与土地特征，按实际场地规划。"};for(var i=0;i<3;i++){var index=i;var box=Card(row,"0"+(i+1)+"  "+names[i],notes[i],i==0?Blue:i==1?Green:Gold);Mark(box,i==1?"building":"public",i==0?Blue:i==1?Green:Gold,160);Button(box,"在此登陆",()=>Command(g=>g.select_block(index)),true);}}
  else {Label(_body,"为城市选定本次起源",27);var row=Row(_body,"Origins",420);foreach(var choice in S["origin_choices"]){var id=choice.Text;var origin=G.c.origins[id];var box=Card(row,origin.Get("name",id).Text,origin.Get("description",origin.Get("summary","")).Text,Gold);Mark(box,"building",Green,130);Metric(box,"起始补充通货",F(origin.Get("cash",0).Double,0));foreach(var resource in new[]{"food","material","goods"})if(origin.Get(resource,0).Double!=0)Metric(box,Resource(resource),Signed(origin[resource].Double));Button(box,"确立起源 · 安顿居民",()=>{Command(g=>g.choose_origin(id));CloseArchive();},true);}}
 }
 void OverviewPage(){var row=Row(_body,"City Summary",240);var civic=Card(row,"河谷现场",Clock.summary(G)["date"].Text,Green);Mark(civic,"building",Green,86);Metric(civic,"已安置 / 待安置",F(S["metrics"].Get("housed",0).Double)+" / "+F(S["metrics"].Get("homeless",0).Double)+" 人");var budget=Card(row,"经营预算","通货用于建设与运营；DT用于加速。",Gold);Metric(budget,"通货",F(S["currency"].Double));Metric(budget,"实际净经营",KnownRate(S["metrics"].Get("cashflow",0).Double));var activity=Card(row,"施工与队列","按优先级共享 CP；材料随真实施工消耗。",Blue);Metric(activity,"施工能力",F(Construction.capacity(G))+" CP/月");Metric(activity,"进行中工程",Construction.queue(G).Count.ToString());
  var nav=Row(_body,"Archive Routes",200);foreach(var entry in new[]{new[]{"resources","供给网络","生产、投入、库存与财政"},new[]{"population","居民生活","住房、就业、口粮与服务"},new[]{"themes","城市方向","主题阶段、事件与实际目标"},new[]{"bonuses","构筑与研究","奖励 FIFO、副本与蓝图"}}){var id=entry[0];var box=Card(nav,entry[1],entry[2],Blue);Button(box,"打开档案 ›",()=>Navigate(id));}
  var pending=Bonus.pending(G);if(pending.Count!=0){var box=Card(_body,"待选择的构筑机会","依次领取，候选保留，不因打开页面改变。",Gold);Metric(box,"待选奖励",pending.Count.ToString()+" 份");Button(box,"处理年度与主题奖励",()=>Navigate("settlement"),true);}
  if(Construction.queue(G).Count!=0){var queue=Card(_body,"施工队列","排序：优先级高者在前，同级按稳定项目编号。",Gold);foreach(var job in Construction.queue(G)){var id=job["id"].Text;Meter(queue,job["name"].Text,job["total"].Double-job["work"].Double,job["total"].Double," CP",Gold);Metric(queue,"剩余材料",F(job["material"].Double));var controls=Row(queue);foreach(var priority in new[]{-1,0,1}){var p=priority;Button(controls,p<0?"延后":p>0?"优先":"普通",()=>Command(g=>Construction.set_priority(g,id,p)));}Button(controls,"建筑档案",()=>Navigate("building",id));}}
  var city=Card(_body,"城市视野","点击地图地格进入情境；完整的来源与规则保持可达。",Green);Button(city,"来源 / 规则 / 场 / 运营商",()=>Navigate("sources"));Button(city,"城市记录与声音",()=>Navigate("records"));
 }
 string KnownRate(double value)=>S.Get("simulation_tick",0).Long>0?Signed(value)+" /月":"等待首次实际结算";
 void ResourcesPage(){var m=S["metrics"];var audit=S.Get("audit",V.Map());Label(_body,"当前库存与最近周期实际流向",27);Label(_body,"库存是当前持有量；以下月率来自实际结算，电力使用供需能力口径。",16,Muted);
  foreach(var resource in new[]{"food","material","goods"}){var box=Card(_body,Resource(resource),"本地库存可达性以各建筑和居民分配来源为准。",resource=="food"?Green:resource=="material"?Gold:Blue);Meter(box,"当前全城库存",G.inventory_total(resource),G.stock_cap(resource)," 单位",Blue);var receipt=audit.Get("resources",V.Map()).Get(resource,V.Map());var elapsed=audit.Get("hours",0).Double;
   if(elapsed>0){var chain=Row(box,"Resource Flow",70);foreach(var pair in new[]{new[]{"produced","本地产出"},new[]{"imported","实际进口"},new[]{"consumed","真实消费"},new[]{"exported","实际外运"},new[]{"lost","损耗"}}){var column=Column(chain,"Flow",2);Label(column,pair[1],15,Muted);Label(column,F(receipt.Get(pair[0],0).Double/elapsed)+" /月",21,pair[0]=="produced"||pair[0]=="imported"?Green:Gold);}Metric(box,"净库存变化",KnownRate(m.Get("flows",V.Map()).Get(resource,0).Double));}else Label(box,"尚未产生实际结算记录。",17,Muted);
   var actions=Row(box);Button(actions,"地图定位 · "+Resource(resource),()=>{SetLayer(resource);CloseArchive();});Button(actions,"管理贸易订单",()=>Navigate("market",resource));Fold(box,"各建筑库存与实际活动来源",c=>{foreach(var id in Rules.ids(S["projects"])){var p=S["projects"][id];var inv=p["inventory"].Get(resource,0).Double;var cap=G.stock_cap_for(id.Text,resource);if(inv>0||cap>0)Meter(c,G.project_name(id.Text),inv,cap," 单位",Blue);foreach(var item in m.Get("activity_ledger",V.Map()).Get(id,V.Arr()))if(item.Get("resource","").Text==resource){Label(c,G.project_name(id.Text)+" · "+(item.Get("kind","").Text=="input"?"投入":"产出")+" "+F(item.Get("rate",0).Double,3)+"/月 · 来源 "+item.Get("source",item.Get("source_id","本楼")).Text,15,Muted);Fold(c,"原始活动凭据",raw=>Raw(raw,item));}}});
  }
  var energy=Card(_body,"全城电力供需","电力是供需能力，统一按全城满足比例分配，不是累计库存或空间电网。",Gold);Meter(energy,"实际供给 / 需求",m.Get("energy",0).Double,m.Get("energy_need",0).Double," 能力",Gold);Metric(energy,"满足率",F(100*m.Get("energy_ratio",1).Double)+"%");Button(energy,"查看电力来源图层",()=>{SetLayer("energy");CloseArchive();});
  var cash=Card(_body,"财政与流水","经营现金流、市场成交和主动操作分别记录。",Gold);Metric(cash,"通货余额",F(S["currency"].Double));Metric(cash,"经营收入",KnownRate(m.Get("income",0).Double));Metric(cash,"维护支出",KnownRate(m.Get("upkeep",0).Double));Metric(cash,"经营净额",KnownRate(m.Get("cashflow",0).Double));HistoryChart(cash,S.Get("civic032",V.Map()).Get("history",V.Arr()),"balance","通货历史 · 已有实际记录",Gold);Fold(cash,"主动操作与市场收支",c=>{foreach(var item in S.Get("civic032",V.Map()).Get("transactions",V.Arr()).Reverse().Take(80))Label(c,F(item["h"].Double)+" 月 · "+item["label"].Text+" · "+Signed(item["cash"].Double)+"通货 · 余额 "+F(item["balance"].Double),15,Muted);});
 }
 void HistoryChart(Transform parent,V history,string key,string title,Color color){var records=history.Where(item=>item.Has(key)&&item[key].IsNumber&&item.Get("h").IsNumber).ToArray();if(records.Length<2){Label(parent,title+"：记录尚不足，未知值不画成零。",14,Muted);return;}Label(parent,title+" · 横轴来生月 / 纵轴实际通货",15,Muted);var r=Node("Measured History",parent);Height(r,260);var chart=r.gameObject.AddComponent<XCharts.Runtime.LineChart>();chart.Init();chart.UpdateTheme(XCharts.Runtime.ThemeType.Dark);chart.theme.sharedTheme.font=_font;chart.theme.transparentBackground=true;chart.EnsureChartComponent<XCharts.Runtime.Title>().show=false;chart.EnsureChartComponent<XCharts.Runtime.Tooltip>().show=true;chart.EnsureChartComponent<XCharts.Runtime.Legend>().show=false;var x=chart.EnsureChartComponent<XCharts.Runtime.XAxis>();var y=chart.EnsureChartComponent<XCharts.Runtime.YAxis>();x.type=XCharts.Runtime.Axis.AxisType.Category;y.type=XCharts.Runtime.Axis.AxisType.Value;x.splitNumber=8;x.boundaryGap=false;var grid=chart.EnsureChartComponent<XCharts.Runtime.GridCoord>();grid.left=80;grid.right=25;grid.top=22;grid.bottom=45;chart.RemoveData();var serie=chart.AddSerie<XCharts.Runtime.Line>(title);serie.lineStyle.color=color;serie.animation.enable=!Runtime.DisplaySettings.Get("reduced_motion",false).Bool;foreach(var item in records){chart.AddXAxisData(F(item["h"].Double,2));chart.AddData(0,item[key].Double);}chart.RefreshChart();}

 void PopulationPage(){var m=S["metrics"];var homes=Card(_body,"居民与住房","住户保留身份；迁入按来生本地时间，服务使用真实有限名额。",Green);Meter(homes,"已安置 / 住房容量",m.Get("housed",0).Double,m.Get("housing",0).Double," 人",Green);Metric(homes,"待安置人口",F(m.Get("homeless",0).Double)+" 人");var controls=Row(homes);Button(controls,S.Get("migration_paused",false).Bool?"恢复迁入":"暂停迁入",()=>Command(g=>{g.toggle_migration();return "";}));Button(controls,S.Get("goods_active",false).Bool?"生活用品消费已启用":"公布生活用品计划",()=>Command(g=>g.enable_goods()),false,S.Get("goods_active",false).Bool);
  var living=Card(_body,"生活满足率","覆盖范围不等于实际服务人数；以已收到的口粮和名额为准。",Blue);foreach(var kind in new[]{"food","medical","education","entertainment","commercial"}){var ratio=kind=="food"?Progress.food_ratio(G):Progress.service_ratio(G,kind);Meter(living,kind=="food"?"实际口粮":Service(kind),ratio*100,100," %",ratio<.75?Gold:Blue);}Metric(living,"平均健康 / 幸福",F(m.Get("health",0).Double)+" / "+F(m.Get("happiness",0).Double));
  foreach(var gid in Rules.ids(S["groups"])){var group=S["groups"][gid];var host=group["host"].Text;var card=Card(_body,G.project_name(host)+" · "+F(group["count"].Double)+"人","住户 "+gid.Text,Green);var row=Row(card,"Resident Measures",50);Label(row,"健康 "+F(group["health"].Double),20);Label(row,"幸福 "+F(group["happiness"].Double),20);Label(row,"教育 "+F(group.Get("education",0).Double),20);var before=group.Get("living",V.Map());Metric(card,"失业比例",F(before.Get("unemployment",1).Double*100)+"%");Metric(card,"污染暴露",F(before.Get("pollution",0).Double,3));if(host!="homeless")Button(card,"定位住宅 / 建筑档案",()=>{SelectBuilding(host);Navigate("building",host);});Fold(card,"工作、口粮与服务完整来源",c=>{Raw(c,group);foreach(var link in m.Get("employment_links",V.Arr()))if(link.Get("source",link.Get("group",link.Get("group_id",""))).Text==gid.Text)Raw(c,link);foreach(var link in m.Get("service_links",V.Arr()))if(link.Get("home","").Text==host)Label(c,Service(link.Get("kind","").Text)+" ← "+G.project_name(link.Get("source","").Text)+" · "+F(link.Get("people",0).Double)+"人",15,Muted);});}
  var workers=Card(_body,"实际就业网络","连接展示来源住区、目标岗位与实际分配。",Blue);foreach(var link in m.Get("employment_links",V.Arr())){var row=Row(workers);var gid=link.Get("source",link.Get("group_id","")).Text;var home=S["groups"].Get(gid,V.Map()).Get("host",link.Get("home","")).Text;Label(row,G.project_name(home)+" → "+G.project_name(link.Get("target","").Text),17);Label(row,F(link.Get("people",0).Double)+" 人",20,Blue);}Button(workers,"打开就业图层",()=>{SetLayer("employment");CloseArchive();});
 }
 void RenderStatus(){if(PointerBusy){_statusDirty=true;return;}_statusDirty=false;var displayKey=StatusDisplayKey();if(displayKey==_statusKey)return;_statusKey=displayKey;StatusRebuildCount++;Clear(_status);Clear(_speech);var summaries=_feedbackView.Get("summaries",V.Arr());foreach(var alert in summaries.Take(2)){var source=alert;var box=Card(_status,alert["text"].Text,"实际结算 · 可定位来源",alert["severity"].Long==2?Red:Gold);Button(box,"定位并查看",()=>{if(_archiveOpen)CloseArchive();SelectBuilding(source["building_id"].Text);SetLayer(source["layer"].Text);});}if(summaries.Count>2)Button(_status,"还有 "+(summaries.Count-2)+" 类警报 ›",()=>OpenArchive("records"));
  var theme=_statusTheme;if(theme.Get("id","").Text!=""){var box=Card(_status,theme["name"].Text,"第 "+theme["stage"].Long+" 阶段 · "+theme["stage_name"].Text,theme["completed"].Bool?Gold:Green);var goals=theme["goals"];var goal=goals.FirstOrDefault(x=>!x["met"].Bool);if(goal!=null)Meter(box,goal["label"].Text,goal["value"].Double,goal["target"].Double," "+goal["unit"].Text,Gold);else Label(box,theme["completed"].Bool?"主题已达成":"本阶段状态条件满足",15,Green);Button(box,"主题档案 ›",()=>OpenArchive("themes"));}
  if(_statusPending!=0)Button(_status,"待选奖励  "+_statusPending+"份",()=>OpenArchive("settlement"),true);
  if(Runtime.DisplaySettings.Get("citizen_bubbles",false).Bool)foreach(var bubble in _feedbackView.Get("bubbles",V.Arr())){var item=bubble;var box=Card(_speech,bubble["text"].Text,"市民体验 · 有实际变化依据",Muted);Button(box,"去看看 ›",()=>{if(_archiveOpen)CloseArchive();SelectBuilding(item["building_id"].Text);SetLayer(item["layer"].Text);});}
 }
 void RefreshContext(){if(PointerBusy){_contextDirty=true;return;}_contextDirty=false;var visible=!_mapViewing&&SelectedTile!=""&&S["cells"].Has(SelectedTile);_context.gameObject.SetActive(visible);var displayKey=ContextDisplayKey();if(displayKey==_contextKey)return;_contextKey=displayKey;ContextRebuildCount++;Clear(_context);if(!visible)return;var body=Column(_context,"Context",8);
  if(SelectedBuilding!=""&&S["projects"].Has(SelectedBuilding)){var p=S["projects"][SelectedBuilding];var id=SelectedBuilding;var st=G.project_stats(id);var title=Row(body,"Building Identity",92);Mark(title,G.c.projects[p["def"]].Get("domain","public").Text,Domain(p),88);var words=Column(title,"Identity",2);Label(words,G.project_name(id),24,Domain(p));Label(words,"T"+p.Get("tier",1).Long+" · "+G.c.operators[p["operator_org"]]["name"].Text,14,Muted);
   if(p.Get("paused",false).Bool){Label(body,"运营已暂停",22,Gold);Button(body,"恢复运营",()=>Command(g=>g.set_paused(id,false)),true);}
   else if(p["status"].Text=="construction"||p.Get("upgrade_job",V.Map()).Count!=0){var job=p.Get("upgrade_job",V.Map()).Count!=0?p["upgrade_job"]:p["job"];Meter(body,"施工进度",job["total"].Double-job["work"].Double,job["total"].Double," CP",Gold);Metric(body,"剩余材料",F(job["material"].Double));Label(body,p.Get("bottleneck","共享施工中").Text,15,Muted);Button(body,"调整施工优先级",()=>Navigate("building",id),true);}
   else {var housing=p["status"].Text=="running"?Math.Max(0,st.Get("housing",0).Double*st.Get("efficiency",1).Double):0;var assigned=S["groups"].Values.Where(x=>x["host"].Text==id).Sum(x=>x["count"].Double);if(housing>0)Meter(body,"已入住",assigned,housing," 人",Green);else if(st.Get("trade_capacity",0).Double>0){foreach(var resource in new[]{"food","material","goods"})Meter(body,Resource(resource),p["inventory"].Get(resource,0).Double,G.stock_cap_for(id,resource),"",Blue);}else {var outputs=p.Get("outputs_last",V.Map());foreach(var output in outputs.Keys.Take(2))Metric(body,Resource(output),F(outputs[output].Double)+" /月","",Green);var utilization=S["metrics"].Get("utilization",V.Map()).Get(id,V.Map());Meter(body,"实际运行",utilization.Get("utilization",p.Get("usage",0)).Double,1,"",Blue);if(utilization.Get("bottleneck","").Text!="")Label(body,utilization["bottleneck"].Text,15,Gold);}
    if(st.Get("trade_capacity",0).Double>0)Button(body,"打开市场",()=>Navigate("market"),true);else if(Development.choices(G,id).Count!=0)Button(body,"成长与升级",()=>Navigate("upgrades",id),true);else Button(body,"方案与运营管理",()=>Navigate("building",id),true);
   }Button(body,"详情 ›",()=>Navigate("building",id));
  }else {var tile=S["cells"][SelectedTile];Label(body,"选址 · "+SelectedTile,23,Gold);Label(body,G.c.tags_text(tile["traits"]),14,Muted);if(tile["traits"].Contains("tile.water")){Label(body,"水域地块不能建设。",17,Muted);return;}var types=Row(body,"Foundations",42);foreach(var choice in G.c.v040["progression"]["tier1"]){var baseId=choice.Text;Button(types,(_base==baseId?"✓ ":"")+G.c.projects[baseId]["name"].Text,()=>{_base=baseId;RefreshContext();});}
   var def=G.c.projects[_base];var preview=_contextPreview;if(preview.Get("ok",false).Bool){var outputs=preview["outputs"];foreach(var resource in outputs.Keys.Take(2))Metric(body,Resource(resource),F(outputs[resource].Double)+" /月","下一周期，假定已完工",Green);if(preview["harmed"].Double>0)Label(body,"环境影响：现有 "+F(preview["harmed"].Double,0)+"位住户暴露上升",14,Gold);}
   Label(body,F(def["cost"].Double,0)+"通货 · "+F(def["material"].Double,0)+"材料 · "+F(def["construction_required"].Double)+" CP",16,Gold);Button(body,"比较运营者投标 ›",()=>{var tileId=SelectedTile;Command(g=>g.create_tender(V.Arr(tileId),_base),false);if(S["draft"].Count!=0){_offer="";Navigate("tender");}},true);
  }
 }
